CREATE OR REPLACE FUNCTION matchmaking_private.random_join_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result text := '';
  i integer;
begin
  for i in 1..6 loop
    result := result || substr(alphabet, 1 + floor(random() * length(alphabet))::integer, 1);
  end loop;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.broadcast_match_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_match_id uuid;
  v_topic text;
begin
  if TG_TABLE_NAME = 'matches' then
    v_match_id := coalesce(NEW.id, OLD.id);
    v_topic := coalesce(NEW.topic, OLD.topic);
  else
    v_match_id := coalesce(NEW.match_id, OLD.match_id);
    select m.topic into v_topic from public.matches m where m.id = v_match_id;
  end if;

  if v_topic is not null then
    perform realtime.broadcast_changes(
      v_topic,
      TG_OP,
      TG_OP,
      TG_TABLE_NAME,
      TG_TABLE_SCHEMA,
      NEW,
      OLD
    );
  end if;

  return coalesce(NEW, OLD);
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.cancel_impl()
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  delete from matchmaking_private.quick_queue where user_id = auth.uid();
  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.leave_impl()
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_match public.matches%rowtype;
  v_remaining integer;
  v_new_host uuid;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;

  delete from matchmaking_private.quick_queue q where q.user_id = v_uid;

  select m.*
  into v_match
  from public.matches m
  join public.match_players mp on mp.match_id = m.id
  where mp.user_id = v_uid
    and mp.left_at is null
    and m.status in ('waiting','ready','active')
  order by m.created_at desc
  limit 1
  for update of m;

  if not found then
    return query select * from matchmaking_private.state_impl();
    return;
  end if;

  update public.match_players as mp
  set left_at = now(), ready = false
  where mp.match_id = v_match.id and mp.user_id = v_uid and mp.left_at is null;

  select count(*) into v_remaining
  from public.match_players mp
  where mp.match_id = v_match.id and mp.left_at is null;

  if v_match.status in ('waiting','ready') then
    if v_remaining = 0 then
      update public.matches as m
      set status = 'cancelled', ended_at = now(), updated_at = now(), revision = m.revision + 1
      where m.id = v_match.id;
    else
      if v_match.host_user_id = v_uid then
        select mp.user_id
        into v_new_host
        from public.match_players mp
        where mp.match_id = v_match.id and mp.left_at is null
        order by mp.host_score desc, mp.joined_at, mp.user_id
        limit 1;
      else
        v_new_host := v_match.host_user_id;
      end if;

      update public.matches as m
      set host_user_id = v_new_host,
          status = 'waiting',
          updated_at = now(),
          revision = m.revision + 1
      where m.id = v_match.id;
    end if;
  elsif v_match.status = 'active' and v_match.host_user_id = v_uid then
    update public.matches as m
    set status = 'abandoned', ended_at = now(), updated_at = now(), revision = m.revision + 1
    where m.id = v_match.id;
  else
    update public.matches as m
    set updated_at = now(), revision = m.revision + 1
    where m.id = v_match.id;
  end if;

  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.finish_impl(p_match_id uuid)
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'Authentication required'; end if;

  update public.matches as m
  set status = 'finished', ended_at = now(), updated_at = now(), revision = m.revision + 1
  where m.id = p_match_id
    and m.host_user_id = v_uid
    and m.status = 'active';

  if not found then raise exception 'Only the active host can finish this match'; end if;

  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.set_ready_impl(p_match_id uuid, p_ready boolean)
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_match public.matches%rowtype;
  v_players integer;
  v_ready integer;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;

  select m.* into v_match
  from public.matches m
  where m.id = p_match_id
  for update;

  if not found or v_match.status not in ('waiting','ready') then
    raise exception 'Match is not in a readyable state';
  end if;

  update public.match_players as mp
  set ready = p_ready
  where mp.match_id = p_match_id and mp.user_id = v_uid and mp.left_at is null;

  if not found then raise exception 'You are not an active member of this match'; end if;

  select count(*), count(*) filter (where mp.ready)
  into v_players, v_ready
  from public.match_players mp
  where mp.match_id = p_match_id and mp.left_at is null;

  update public.matches as m
  set status = case when v_players = m.player_count and v_ready = v_players then 'ready' else 'waiting' end,
      updated_at = now(),
      expires_at = greatest(m.expires_at, now() + interval '10 minutes'),
      revision = m.revision + 1
  where m.id = p_match_id;

  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.join_lobby_impl(p_code text, p_display_name text, p_platform text, p_app_version text, p_engine_build text, p_upstream text, p_catalogue_hash text, p_protocol_version integer, p_host_score integer DEFAULT 0)
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_match public.matches%rowtype;
  v_seat smallint;
  v_count integer;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if upper(trim(p_code)) !~ '^[A-HJ-NP-Z2-9]{6}$' then raise exception 'Invalid join code'; end if;
  if char_length(trim(p_display_name)) not between 1 and 32 then raise exception 'Display name must be 1-32 characters'; end if;
  if p_platform not in ('ios','android') then raise exception 'Unsupported platform'; end if;
  if char_length(p_app_version) not between 1 and 80 then raise exception 'Invalid app version'; end if;
  if char_length(p_engine_build) not between 1 and 160 then raise exception 'Invalid engine build'; end if;
  if char_length(p_upstream) not between 7 and 80 then raise exception 'Invalid XMage upstream identity'; end if;
  if char_length(p_catalogue_hash) not between 16 and 160 then raise exception 'Invalid catalogue hash'; end if;
  if p_protocol_version <= 0 then raise exception 'Invalid protocol version'; end if;
  if p_host_score not between 0 and 1000 then raise exception 'Invalid host score'; end if;

  perform matchmaking_private.cleanup();

  select m.*
  into v_match
  from public.matches m
  where m.join_code = upper(trim(p_code))
    and m.kind = 'private'
    and m.status in ('waiting','ready')
    and m.expires_at > now()
  for update;

  if not found then raise exception 'Lobby not found or expired'; end if;

  if v_match.protocol_version <> p_protocol_version
     or v_match.upstream <> p_upstream
     or v_match.catalogue_hash <> p_catalogue_hash then
    raise exception 'XMage rules/catalogue/protocol do not match this lobby';
  end if;

  if exists (
    select 1
    from public.match_players mp
    join public.matches m on m.id = mp.match_id
    where mp.user_id = v_uid and mp.left_at is null
      and m.status in ('waiting','ready','active')
      and m.id <> v_match.id
  ) then
    raise exception 'Leave your current match before joining another lobby';
  end if;

  delete from matchmaking_private.quick_queue where user_id = v_uid;

  if exists (
    select 1 from public.match_players mp
    where mp.match_id = v_match.id and mp.user_id = v_uid and mp.left_at is null
  ) then
    return query select * from matchmaking_private.state_impl();
    return;
  end if;

  select count(*) into v_count
  from public.match_players mp
  where mp.match_id = v_match.id and mp.left_at is null;

  if v_count >= v_match.player_count then raise exception 'Lobby is full'; end if;

  select s::smallint
  into v_seat
  from generate_series(0, v_match.player_count - 1) s
  where not exists (
    select 1 from public.match_players mp
    where mp.match_id = v_match.id and mp.seat = s and mp.left_at is null
  )
  order by s
  limit 1;

  if v_seat is null then raise exception 'Lobby has no free seat'; end if;

  insert into public.match_players(
    match_id, user_id, seat, display_name, platform, app_version,
    engine_build, upstream, catalogue_hash, protocol_version, host_score, ready, joined_at, left_at
  ) values (
    v_match.id, v_uid, v_seat, trim(p_display_name), p_platform, p_app_version,
    p_engine_build, p_upstream, p_catalogue_hash, p_protocol_version, p_host_score, false, now(), null
  )
  on conflict (match_id, user_id) do update set
    seat = excluded.seat,
    display_name = excluded.display_name,
    platform = excluded.platform,
    app_version = excluded.app_version,
    engine_build = excluded.engine_build,
    upstream = excluded.upstream,
    catalogue_hash = excluded.catalogue_hash,
    protocol_version = excluded.protocol_version,
    host_score = excluded.host_score,
    ready = false,
    joined_at = now(),
    left_at = null;

  update public.matches as m
  set status = 'waiting',
      updated_at = now(),
      expires_at = greatest(m.expires_at, now() + interval '15 minutes'),
      revision = m.revision + 1
  where m.id = v_match.id;

  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.consume_rate_limit(p_action text, p_limit integer, p_window interval)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row matchmaking_private.rate_limits%rowtype;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_limit < 1 or p_window <= interval '0 seconds' then raise exception 'Invalid rate limit configuration'; end if;

  insert into matchmaking_private.rate_limits(user_id, action, window_start, request_count)
  values (v_uid, p_action, now(), 1)
  on conflict (user_id, action) do nothing;

  select rl.* into v_row
  from matchmaking_private.rate_limits rl
  where rl.user_id = v_uid and rl.action = p_action
  for update;

  if v_row.window_start <= now() - p_window then
    update matchmaking_private.rate_limits rl
    set window_start = now(), request_count = 1
    where rl.user_id = v_uid and rl.action = p_action;
  elsif v_row.request_count >= p_limit then
    raise exception 'Too many requests. Please wait and try again.';
  else
    update matchmaking_private.rate_limits rl
    set request_count = rl.request_count + 1
    where rl.user_id = v_uid and rl.action = p_action;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.enqueue_impl(p_display_name text, p_platform text, p_app_version text, p_engine_build text, p_upstream text, p_catalogue_hash text, p_protocol_version integer, p_player_count smallint, p_host_score integer DEFAULT 0)
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_other_ids uuid[];
  v_all_ids uuid[];
  v_match_id uuid;
  v_host uuid;
  v_host_build text;
  r record;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if char_length(trim(p_display_name)) not between 1 and 32 then raise exception 'Display name must be 1-32 characters'; end if;
  if p_platform not in ('ios','android') then raise exception 'Unsupported platform'; end if;
  if char_length(p_app_version) not between 1 and 80 then raise exception 'Invalid app version'; end if;
  if char_length(p_engine_build) not between 1 and 160 then raise exception 'Invalid engine build'; end if;
  if char_length(p_upstream) not between 7 and 80 then raise exception 'Invalid XMage upstream identity'; end if;
  if char_length(p_catalogue_hash) not between 16 and 160 then raise exception 'Invalid catalogue hash'; end if;
  if p_protocol_version <= 0 then raise exception 'Invalid protocol version'; end if;
  if p_player_count not between 2 and 4 then raise exception 'Player count must be 2-4'; end if;
  if p_host_score not between 0 and 1000 then raise exception 'Invalid host score'; end if;

  perform matchmaking_private.cleanup();

  if exists (
    select 1
    from public.match_players mp
    join public.matches m on m.id = mp.match_id
    where mp.user_id = v_uid and mp.left_at is null
      and m.status in ('waiting','ready','active')
  ) then
    return query select * from matchmaking_private.state_impl();
    return;
  end if;

  insert into matchmaking_private.quick_queue(
    user_id, display_name, platform, app_version, engine_build, upstream, catalogue_hash,
    protocol_version, format, player_count, host_score, joined_at, expires_at
  ) values (
    v_uid, trim(p_display_name), p_platform, p_app_version, p_engine_build, p_upstream, p_catalogue_hash,
    p_protocol_version, 'commander', p_player_count, p_host_score, now(), now() + interval '3 minutes'
  )
  on conflict (user_id) do update set
    display_name = excluded.display_name,
    platform = excluded.platform,
    app_version = excluded.app_version,
    engine_build = excluded.engine_build,
    upstream = excluded.upstream,
    catalogue_hash = excluded.catalogue_hash,
    protocol_version = excluded.protocol_version,
    format = excluded.format,
    player_count = excluded.player_count,
    host_score = excluded.host_score,
    joined_at = case
      when matchmaking_private.quick_queue.upstream = excluded.upstream
       and matchmaking_private.quick_queue.catalogue_hash = excluded.catalogue_hash
       and matchmaking_private.quick_queue.protocol_version = excluded.protocol_version
       and matchmaking_private.quick_queue.player_count = excluded.player_count
       and matchmaking_private.quick_queue.format = excluded.format
      then matchmaking_private.quick_queue.joined_at
      else now()
    end,
    expires_at = now() + interval '3 minutes';

  select array_agg(x.user_id order by x.joined_at)
  into v_other_ids
  from (
    select q.user_id, q.joined_at
    from matchmaking_private.quick_queue q
    where q.user_id <> v_uid
      and q.expires_at > now()
      and q.format = 'commander'
      and q.player_count = p_player_count
      and q.protocol_version = p_protocol_version
      and q.upstream = p_upstream
      and q.catalogue_hash = p_catalogue_hash
    order by q.joined_at
    for update skip locked
    limit (p_player_count - 1)
  ) x;

  if coalesce(array_length(v_other_ids, 1), 0) = p_player_count - 1 then
    v_all_ids := array_prepend(v_uid, v_other_ids);

    select q.user_id, q.engine_build
    into v_host, v_host_build
    from matchmaking_private.quick_queue q
    where q.user_id = any(v_all_ids)
    order by q.host_score desc, q.joined_at asc, q.user_id
    limit 1;

    v_match_id := gen_random_uuid();

    insert into public.matches(
      id, topic, kind, format, player_count, status, join_code,
      created_by, host_user_id, protocol_version, engine_build, upstream, catalogue_hash,
      revision, created_at, updated_at, expires_at
    ) values (
      v_match_id, 'match:' || v_match_id::text || ':lobby', 'quick', 'commander',
      p_player_count, 'waiting', null, v_uid, v_host,
      p_protocol_version, v_host_build, p_upstream, p_catalogue_hash,
      1, now(), now(), now() + interval '10 minutes'
    );

    insert into public.match_players(
      match_id, user_id, seat, display_name, platform, app_version,
      engine_build, upstream, catalogue_hash, protocol_version, host_score, ready, joined_at
    )
    select
      v_match_id,
      q.user_id,
      (row_number() over (
        order by case when q.user_id = v_host then 0 else 1 end, q.joined_at, q.user_id
      ) - 1)::smallint,
      q.display_name,
      q.platform,
      q.app_version,
      q.engine_build,
      q.upstream,
      q.catalogue_hash,
      q.protocol_version,
      q.host_score,
      false,
      now()
    from matchmaking_private.quick_queue q
    where q.user_id = any(v_all_ids);

    delete from matchmaking_private.quick_queue
    where user_id = any(v_all_ids);

    for r in
      select mp.user_id
      from public.match_players mp
      where mp.match_id = v_match_id
    loop
      perform realtime.send(
        jsonb_build_object('match_id', v_match_id, 'topic', 'match:' || v_match_id::text || ':lobby'),
        'match_found',
        'queue:' || r.user_id::text,
        true
      );
    end loop;
  end if;

  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.create_lobby_impl(p_display_name text, p_platform text, p_app_version text, p_engine_build text, p_upstream text, p_catalogue_hash text, p_protocol_version integer, p_player_count smallint, p_host_score integer DEFAULT 0)
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_code text;
  tries integer := 0;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if char_length(trim(p_display_name)) not between 1 and 32 then raise exception 'Display name must be 1-32 characters'; end if;
  if p_platform not in ('ios','android') then raise exception 'Unsupported platform'; end if;
  if char_length(p_app_version) not between 1 and 80 then raise exception 'Invalid app version'; end if;
  if char_length(p_engine_build) not between 1 and 160 then raise exception 'Invalid engine build'; end if;
  if char_length(p_upstream) not between 7 and 80 then raise exception 'Invalid XMage upstream identity'; end if;
  if char_length(p_catalogue_hash) not between 16 and 160 then raise exception 'Invalid catalogue hash'; end if;
  if p_protocol_version <= 0 then raise exception 'Invalid protocol version'; end if;
  if p_player_count not between 2 and 4 then raise exception 'Player count must be 2-4'; end if;
  if p_host_score not between 0 and 1000 then raise exception 'Invalid host score'; end if;

  perform matchmaking_private.cleanup();

  if exists (
    select 1
    from public.match_players mp
    join public.matches m on m.id = mp.match_id
    where mp.user_id = v_uid and mp.left_at is null
      and m.status in ('waiting','ready','active')
  ) then
    raise exception 'Leave your current match before creating another lobby';
  end if;

  delete from matchmaking_private.quick_queue where user_id = v_uid;

  loop
    tries := tries + 1;
    if tries > 20 then raise exception 'Could not allocate join code'; end if;
    v_id := gen_random_uuid();
    v_code := matchmaking_private.random_join_code();
    begin
      insert into public.matches(
        id, topic, kind, format, player_count, status, join_code,
        created_by, host_user_id, protocol_version, engine_build, upstream, catalogue_hash,
        revision, created_at, updated_at, expires_at
      ) values (
        v_id, 'match:' || v_id::text || ':lobby', 'private', 'commander',
        p_player_count, 'waiting', v_code, v_uid, v_uid,
        p_protocol_version, p_engine_build, p_upstream, p_catalogue_hash,
        1, now(), now(), now() + interval '30 minutes'
      );
      exit;
    exception when unique_violation then
      null;
    end;
  end loop;

  insert into public.match_players(
    match_id, user_id, seat, display_name, platform, app_version,
    engine_build, upstream, catalogue_hash, protocol_version, host_score, ready, joined_at
  ) values (
    v_id, v_uid, 0, trim(p_display_name), p_platform, p_app_version,
    p_engine_build, p_upstream, p_catalogue_hash, p_protocol_version, p_host_score, false, now()
  );

  return query select * from matchmaking_private.state_impl();
end;
$function$

CREATE OR REPLACE FUNCTION matchmaking_private.start_impl(p_match_id uuid)
 RETURNS TABLE(state text, queue_topic text, match_id uuid, match_topic text, join_code text, seat smallint, is_host boolean, player_count smallint, match_status text, protocol_version integer, engine_build text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_match public.matches%rowtype;
  v_players integer;
  v_ready integer;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;

  select m.* into v_match
  from public.matches m
  where m.id = p_match_id
  for update;

  if not found then raise exception 'Match not found'; end if;
  if v_match.host_user_id <> v_uid then raise exception 'Only the host can start the match'; end if;
  if v_match.status = 'active' then
    return query select * from matchmaking_private.state_impl();
    return;
  end if;
  if v_match.status <> 'ready' then raise exception 'All seats must be filled and ready first'; end if;

  select count(*), count(*) filter (where mp.ready)
  into v_players, v_ready
  from public.match_players mp
  where mp.match_id = p_match_id and mp.left_at is null;

  if v_players <> v_match.player_count or v_ready <> v_players then
    raise exception 'All seats must be filled and ready first';
  end if;

  insert into matchmaking_private.match_transport(match_id, transport_key)
  values (p_match_id, replace(gen_random_uuid()::text, '-', ''))
  on conflict on constraint match_transport_pkey do nothing;

  update public.matches as m
  set status = 'active',
      started_at = coalesce(m.started_at, now()),
      updated_at = now(),
      expires_at = now() + interval '6 hours',
      revision = m.revision + 1
  where m.id = p_match_id;

  return query select * from matchmaking_private.state_impl();
end;
